// УЧЕБНЫЙ ПРИМЕР. Не является анонимизацией и не предназначен для реальных ПД.
// Исходный текст остаётся виден в предыдущем узле и может попасть в историю executions.
const rows = $input.all();
return rows.map(({json:j}) => {
  const source = String(j.text ?? '');
  const flags = [];
  if (/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i.test(source)) flags.push('email');
  if (/(?:\+7|8)[\s(-]*\d{3}[\s)-]*\d{3}[\s-]*\d{2}[\s-]*\d{2}/.test(source)) flags.push('phone');
  if (/парол[ья]|secret|token|api[_ -]?key|ключ доступ[а-я]*/i.test(source)) flags.push('possible_secret');
  const cleaned = source
    .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[EMAIL]')
    .replace(/(?:\+7|8)[\s(-]*\d{3}[\s)-]*\d{3}[\s-]*\d{2}[\s-]*\d{2}/g, '[PHONE]');
  return {json:{case_id:j.case_id, clean_text:cleaned, route:flags.length?'review':'safe', flags, note:'Учебная проверка. Отсутствие флагов НЕ доказывает анонимность.'}};
});
